// ❌ OLD: The Stack Reconciler used deep recursion over the component tree.
// Once rendering started, the JS engine call stack was locked until every
// single leaf node finished rendering, freezing input and animations on large trees.
function reconcileChildren(parent, children) {
  for (let i = 0; i < children.length; i++) {
    // Recursive call stack locks the browser main thread:
    mountComponent(children[i]);
  }
}

// ✅ NEW: Conceptual representation of the Fiber work loop.
// Iterative linked-list traversal yields to the browser when the 5ms time slice expires.
function workLoopConcurrent() {
  while (workInProgress !== null && !shouldYieldToHost()) {
    workInProgress = performUnitOfWork(workInProgress);
  }
}

function performUnitOfWork(unitOfWork) {
  const current = unitOfWork.alternate;
  let next = beginWork(current, unitOfWork, renderLanes);
  unitOfWork.memoizedProps = unitOfWork.pendingProps;

  if (next === null) {
    // Reached bottom of branch, step to sibling or return to parent:
    completeUnitOfWork(unitOfWork);
  }
  return next;
}
